1|// Rust rewrite of BILLBATCH.
2|//
3|// Reads the fixed-width file (34-char records), writes the same
4|// detail lines and TOTALS line the COBOL report uses. Build with
5|// rustc (no crates):  rustc -O wonder-bill.rs -o /tmp/wonder-bill
6|// Run where patients.dat lives (filenames are fixed):  /tmp/wonder-bill
7|//
8|//
9|//
10|//
11|//
12|use std::fs;
13|use std::io::Write;
14|
15|fn money(cents: i64, width: usize) -> String {
16|    // COBOL edited-picture rule ($$$,$$9.99 style): one floating $ and
17|    // one comma, the comma before the last three integer digits.
18|    let int = format!("{}", cents / 100);
19|    let int = if int.len() > 3 {
20|        let (hi, lo) = int.split_at(int.len() - 3);
21|        format!("{},{}", hi, lo)
22|    } else {
23|        int
24|    };
25|    let out = format!("${}.{:02}", int, cents.rem_euclid(100));
26|    format!("{:>width$}", out, width = width)
27|}
28|
29|fn fee_cents(balance_cents: i64) -> i64 {
30|    (balance_cents * 15 + 500) / 1000
31|}
32|
33|fn main() {
34|    let data = fs::read_to_string("patients.dat").expect("patients.dat");
35|    let mut out = fs::File::create("rewrite-report.txt").expect("output");
36|    let mut total_balance: i64 = 0;
37|    let mut total_fee: i64 = 0;
38|    let mut count = 0;
39|    for line in data.lines() {
40|        if line.is_empty() {
41|            continue;
42|        }
43|        let acct = &line[0..6];
44|        let name = &line[6..26];
45|        let balance: i64 = line[26..33].parse().expect("balance");
46|        //
47|        let fee = fee_cents(balance);
48|        total_balance += balance;
49|        total_fee += fee;
50|        count += 1;
51|        writeln!(
52|            out,
53|            "ACCT {} NAME  {} BALANCE {} FEE {}",
54|            acct,
55|            name,
56|            money(balance, 10),
57|            money(fee, 10)
58|        )
59|        .expect("write");
60|    }
61|    writeln!(
62|        out,
63|        "TOTALS RECORDS  {:>4} BALANCE {} FEE {}",
64|        count,
65|        money(total_balance, 12),
66|        money(total_fee, 10)
67|    )
68|    .expect("write");
69|}

